INSERT INTO legion_seat_path_guard SELECT COUNT(*)=2 FROM creature_addon a JOIN creature c ON c.guid=a.guid WHERE a.guid IN(342743,342793) AND a.path_id=12961265 AND c.id=118786 AND c.map=1220;
